import os
import requests


def compare_metric_series(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("DATADOG_API_KEY")
    app_key = config.get("app_key") or os.getenv("DATADOG_APP_KEY")
    site = config.get("site") or os.getenv("DATADOG_SITE", "datadoghq.com")
    if not api_key or not app_key:
        raise ValueError("Datadog API key and APP key are required")

    metric_name = payload["metric_name"]
    start = int(payload["start"])
    end = int(payload["end"])
    resource_a = payload["resource_a"]
    resource_b = payload["resource_b"]
    window = int(payload.get("window", 60))
    aggregation = payload.get("aggregation", "avg")

    def _normalize_filter(resource):
        if isinstance(resource, str):
            return resource
        if isinstance(resource, dict):
            parts = []
            for key, value in resource.items():
                if isinstance(value, (list, tuple, set)):
                    for item in value:
                        parts.append(f"{key}:{item}")
                else:
                    parts.append(f"{key}:{value}")
            return ",".join(parts)
        raise TypeError("resource filters must be a string or dict")

    def _query_for(resource_filter):
        normalized = _normalize_filter(resource_filter)
        query = f"{aggregation}:{metric_name}{{{normalized}}}"
        return {
            "data": {
                "type": "metric_intelligent_timeseries_request",
                "attributes": {
                    "formulas": [{"formula": "query1"}],
                    "queries": [
                        {
                            "data_source": "metrics",
                            "name": "query1",
                            "query": query,
                            "aggregator": aggregation,
                        }
                    ],
                    "from": start,
                    "to": end,
                    "interval": window,
                },
            }
        }

    headers = {
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key,
        "Content-Type": "application/json",
    }

    def _fetch(resource_filter):
        url = f"https://api.{site}/api/v2/queries/timeseries"
        response = requests.post(url, headers=headers, json=_query_for(resource_filter), timeout=30)
        response.raise_for_status()
        data = response.json()
        series = (
            data.get("data", {})
            .get("attributes", {})
            .get("series", [])
        )
        points = []
        if series:
            first = series[0]
            for point in first.get("pointlist", []) or []:
                if point and len(point) >= 2:
                    points.append(point[1])
        return {
            "query": _normalize_filter(resource_filter),
            "points": points,
            "avg": sum(points) / len(points) if points else None,
            "min": min(points) if points else None,
            "max": max(points) if points else None,
            "count": len(points),
        }

    result = {"a": _fetch(resource_a), "b": _fetch(resource_b)}
    return result
